def word_frequencies(words):
    """Return a dict mapping each word in words to its occurrence count.

    Order of first appearance is preserved by dict insertion order. An
    empty input yields an empty dict.
    """
    counts = {}
    for word in words:
        if word in counts:
            counts[word] += 1
        else:
            counts[word] = 1
    return counts
